fn apply_block_for_absorb(block: &mut DocxBlock, diff: &DocxBlockDiff) {
    match diff {
        DocxBlockDiff::Replace { block: new } => *block = new.clone(),
        DocxBlockDiff::Paragraph(pd) => {
