                }
            }
        }
        DocxBlockDiff::Table(td) => {
            if let DocxBlock::Table(table) = block {
                if let Some(rows) = &td.rows {
                    apply_indexed_for_absorb(&mut table.rows, rows, apply_row_for_absorb);
                }
                if let Some(extra) = &td.extra_table_properties {
